package com.example.rokidgeminisecretary;
import org.json.*;import java.util.*;
final class ComposerReceiptSummary {
 static String describe(JSONArray rows){ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null)list.add(row);}list.sort((a,b)->Long.compare(b.optLong("time"),a.optLong("time")));StringBuilder out=new StringBuilder("直近の会話送信（スマホ・Web共通）");for(int i=0;i<Math.min(3,list.size());i++){JSONObject row=list.get(i);String state=row.optBoolean("tracked")&&TrackedWebRequest.validId(row.optString("key"))?row.optString("requestState"):"",label=state.equals("QUEUED")||state.equals("CREATED")?"受付・送信待ち":state.equals("RECEIVED")?"グラス受付済み":state.equals("RUNNING")?"処理中":state.equals("ANSWERED")?"メガネ回答完了・本文は送信状況で確認":state.equals("FAILED")?(row.optString("receiptReason").equals("NETWORK")?"AI通信失敗・結果要確認":"回答未完了"):state.equals("CANCELLED")?"送信前に取消済み":state.equals("SUPERSEDED")?"編集した依頼へ差し替え済み":state.equals("STOPPED")?"回答待ちを中止済み":"結果未確認";String id=row.optString("key"),message=row.optString("message").replaceAll("[\\r\\n]+"," ");out.append("\n").append(label).append("・").append(id.substring(0,Math.min(8,id.length()))).append(" ").append(message.substring(0,message.offsetByCodePoints(0,Math.min(24,message.codePointCount(0,message.length())))));}return list.isEmpty()?"会話の送信記録はまだありません":out.toString();}
 private ComposerReceiptSummary(){}
}
